// Open first, newest first, max 50 (contract: escalations).
const rows = $input.all().map((i) => i.json).filter((r) => r && r.sender_id);
rows.sort((a, b) => (a.status === 'open' ? 0 : 1) - (b.status === 'open' ? 0 : 1)
  || String(b.escalated_at || '').localeCompare(String(a.escalated_at || '')));
return [{ json: { items: rows.slice(0, 50).map((r) => ({ sender_id: String(r.sender_id), platform: r.platform,
  customer_name: r.customer_name || '', reason: r.reason || '', escalated_at: r.escalated_at || '', status: r.status || 'open' })) } }];

// Contract: chat. History rows (oldest first) + bot mode from sales_bot_user_ai_control + latest escalation row.
const b = $('Webhook').first().json.body;
const msgs = $('Load history').all().map((i) => i.json).filter((r) => r && r.message != null);
const ctl = $('Load AI control').first().json;
const esc = $('Escalation Check').all().map((i) => i.json).filter((r) => r && r.sender_id)
  .sort((x, y) => (x.status === 'open' ? 0 : 1) - (y.status === 'open' ? 0 : 1)
    || String(y.escalated_at || '').localeCompare(String(x.escalated_at || '')))[0] || {};
const at = (r) => { const v = r.created_at ?? r.createdAt ?? null; if (v == null) return null; const d = new Date(v); return isNaN(d) ? null : d.toISOString(); };
return [{ json: {
  sender_id: String(b.sender_id), platform: b.platform,
  customer_name: esc.customer_name || ctl.label || '', reason: esc.reason || '',
  mode: ctl && ctl.ai_enabled != null && Number(ctl.ai_enabled) === 0 ? 'human' : 'bot',
  messages: msgs.map((r) => ({ role: r.sender === 'bot' ? 'bot' : 'customer', text: String(r.message), at: at(r) })),
} }];

// Unified inbox: every known conversation + its latest escalation.
const ctl = $('Conversations control').all().map((i) => i.json).filter((r) => r && r.sender_id != null);
const esc = $input.all().map((i) => i.json).filter((r) => r && r.sender_id != null);
const key = (r) => String(r.platform) + '/' + String(r.sender_id);
const iso = (v) => {
  if (v == null || v === '') return null;
  const d = new Date(v);
  return isNaN(d.getTime()) ? null : d.toISOString();
};
const map = new Map();

for (const r of ctl) {
  const platform = String(r.platform || '').toLowerCase();
  if (!['facebook', 'whatsapp'].includes(platform)) continue;
  const human = Number(r.ai_enabled) === 0;
  map.set(key({ platform, sender_id: r.sender_id }), {
    sender_id: String(r.sender_id),
    platform,
    customer_name: String(r.label || ''),
    last_message: String(r.last_message || ''),
    last_seen: iso(r.last_seen),
    mode: human ? 'human' : 'bot',
    status: human ? 'open' : 'active',
    reason: '',
    escalated_at: iso(r.escalated_at),
  });
}

for (const r of esc) {
  const platform = String(r.platform || '').toLowerCase();
  if (!['facebook', 'whatsapp'].includes(platform)) continue;
  const k = key({ platform, sender_id: r.sender_id });
  const cur = map.get(k) || {
    sender_id: String(r.sender_id),
    platform,
    customer_name: '',
    last_message: '',
    last_seen: null,
    mode: 'human',
    status: 'open',
    reason: '',
    escalated_at: null,
  };
  cur.customer_name = String(r.customer_name || cur.customer_name || '');
  cur.reason = String(r.reason || cur.reason || '');
  cur.escalated_at = iso(r.escalated_at) || cur.escalated_at;
  const status = String(r.status || 'open').toLowerCase();
  if (status === 'open') {
    cur.status = 'open';
    cur.mode = 'human';
  } else if (cur.mode !== 'human') {
    cur.status = 'closed';
  }
  if (!cur.last_seen) cur.last_seen = cur.escalated_at;
  map.set(k, cur);
}

const items = [...map.values()]
  .sort((a, b) => String(b.last_seen || b.escalated_at || '')
    .localeCompare(String(a.last_seen || a.escalated_at || '')))
  .slice(0, 200);
return [{ json: { items } }];

